    seen=set(); comps=[]
    for r in range(H):
      for c in range(W):
       if g[r][c]!=8 and (r,c) not in seen:
        st=[(r,c)]; seen.add((r,c)); comp=[]
        while st:
         a,b=st.pop(); comp.append((a,b))
         for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
          x,y=a+da,b+db
          if 0<=x<H and 0<=y<W and g[x][y]!=8 and (x,y) not in seen:
           seen.add((x,y));st.append((x,y))
        comps.append(comp)
    singles=sorted([p[0] for p in comps if len(p)==1])
    colors=[grid[r][c] for r,c in singles]
    for comp in comps:
      if len(comp)==1: continue
      rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
      r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
      if r1-r0+1>=3 and c1-c0+1==2:
        # Direction from a singleton level with first ray, else asymmetric body.
        aligned=[c for r,c in singles if r==r0+1]
        if aligned: right=aligned[0]>c1
        else: right=grid[r0+2][c1]<grid[r0+2][c0]
        for rr,col in zip((r0+1,r0+4,r0+5),colors):
          for cc in (range(c1+1,W) if right else range(c0)):
            if grid[rr][cc]==8:g[rr][cc]=col
      elif r1-r0+1==2 and c1-c0+1>=3:
        for cc,col in zip((c0+1,c0+2,c0+5),colors):
          for rr in range(r1+1,H):
            if grid[rr][cc]==8:g[rr][cc]=col
    return g
